if (points.size() <= 1) return points;

auto cmp = [&](const std::pair<int, Point2d>& a, const std::pair<int, Point2d>& b) {
    Point2d o = a.second, p = b.second;
    if (o.x == p.x) return o.y < p.y;
    return (p.y - o.y) * (p.x - o.x) < 0;
};

std::vector<std::pair<int, Point2d>> indexedPoints;
for (int i = 0; i < points.size(); i++) {
    indexedPoints.emplace_back(i, points[i]);
}

std::sort(indexedPoints.begin(), indexedPoints.end(), cmp);

Point2d p0 = indexedPoints[0].second;
std::vector<Point2d> hull;
hull.reserve(points.size() + 1);

for (const auto& p : indexedPoints) {
    hull.push_back(p.second);
}

int i = 0;
while (i < hull.size() && hull[i] == p0) i++;
if (i == hull.size()) return hull;

std::vector<Point2d> stack;
stack.reserve(points.size() + 1);
stack.push_back(hull[0]);
stack.push_back(hull[1]);

for (int j = 2; j < hull.size(); j++) {
    Point2d top = stack.back();
    stack.pop_back();
    Point2d next = stack.back();
    Point2d curr = hull[j];

    while (crossProduct(next - top, curr - top) <= 0) {
        top = stack.back();
        stack.pop_back();
        next = stack.back();
    }
    stack.push_back(top);
    stack.push_back(curr);
}

return stack;
// END_CODE

